const input = ($json.body && typeof $json.body === 'object') ? $json.body : ($json || {});

function clean(value) {
  return String(value ?? '').trim();
}

function onlyDigits(value) {
  return clean(value).replace(/\D/g, '');
}

function normalizePhone(value) {
  const digits = onlyDigits(value);
  if (!digits) return '';
  if (digits.startsWith('55')) return digits;
  if (digits.length === 10 || digits.length === 11) return '55' + digits;
  return digits;
}

function splitName(fullName) {
  const parts = clean(fullName).split(/\s+/).filter(Boolean);
  return {
    firstname: parts[0] || '',
    lastname: parts.length > 1 ? parts.slice(1).join(' ') : ''
  };
}

function scoreLead(payload) {
  let score = 40;
  const momento = payload.momento_de_compra.toLowerCase();
  const objetivo = payload.objetivo_do_lead.toLowerCase();
  const perfil = payload.perfil_profissional.toLowerCase();
  const obs = payload.observacao.toLowerCase();

  if (payload.telefone) score += 15;
  if (payload.email) score += 5;
  if (perfil.includes('médico') || perfil.includes('saúde') || perfil.includes('advogado') || perfil.includes('empresário') || perfil.includes('investidor')) score += 10;
  if (objetivo.includes('uso próprio') || objetivo.includes('expansão') || objetivo.includes('presença') || objetivo.includes('investimento')) score += 15;
  if (momento.includes('especialista') || momento.includes('próximos meses') || momento.includes('comparando')) score += 15;
  if (obs.length > 20) score += 10;

  return Math.max(0, Math.min(100, score));
}

const names = splitName(input.nome || input.name);
const payload = {
  nome: clean(input.nome || input.name),
  firstname: names.firstname,
  lastname: names.lastname,
  contato_original: clean(input.whatsapp || input.contato || input.telefone || input.phone || input.email),
  telefone: normalizePhone(input.whatsapp || input.telefone || input.phone || input.contato),
  email: clean(input.email).toLowerCase(),
  perfil_profissional: clean(input.perfil || input.perfil_profissional),
  objetivo_do_lead: clean(input.objetivo || input.objetivo_do_lead),
  momento_de_compra: clean(input.momento || input.momento_de_compra),
  observacao: clean(input.observacao || input.notas),
  consentimento_lgpd: input.consentimento_lgpd === true || input.consentimento_lgpd === 'true',
  honeypot_site: clean(input.honeypot_site || input.site),
  projeto_interesse: clean(input.projeto_interesse || 'Lótus Business'),
  origem_pagina: clean(input.origem_pagina || input.page_url),
  page_url: clean(input.page_url || input.origem_pagina),
  referrer: clean(input.referrer),
  canal_origem: clean(input.canal_origem || input.utm_source || 'wordpress'),
  lead_source: clean(input.lead_source || 'landing_lotus_wordpress'),
  landing_page: 'lotus-landing-public',
  utm_source: clean(input.utm_source),
  utm_medium: clean(input.utm_medium),
  utm_campaign: clean(input.utm_campaign),
  utm_content: clean(input.utm_content),
  utm_term: clean(input.utm_term),
  fbclid: clean(input.fbclid),
  gclid: clean(input.gclid),
  timestamp: clean(input.timestamp || new Date().toISOString()),
  responsavel: 'Alexandre Borges',
  creci: 'CRECI-SC 45148'
};

payload.score_inicial = scoreLead(payload);
payload.temperatura_lead = payload.score_inicial >= 75 ? 'quente' : payload.score_inicial >= 55 ? 'morno' : 'frio';
payload.prioridade = payload.temperatura_lead === 'quente' ? 'alta' : payload.temperatura_lead === 'morno' ? 'media' : 'baixa';
payload.status_qualificacao = payload.temperatura_lead === 'quente' ? 'lead_quente_lotus' : payload.temperatura_lead === 'morno' ? 'lead_morno_lotus' : 'lead_frio_lotus';
payload.lifecyclestage = payload.temperatura_lead === 'quente' ? 'salesqualifiedlead' : 'lead';
payload.criar_deal = payload.temperatura_lead === 'quente' || payload.momento_de_compra.toLowerCase().includes('especialista');
payload.is_valid = Boolean(payload.nome && payload.telefone && payload.consentimento_lgpd && !payload.honeypot_site);
payload.validation_error = payload.is_valid ? '' : 'Nome, WhatsApp e aceite de contato são obrigatórios.';

payload.alert_message = [
  'Novo lead Lótus via landing',
  `Nome: ${payload.nome || '-'}`,
  `WhatsApp: ${payload.telefone || '-'}`,
  payload.email ? `E-mail: ${payload.email}` : '',
  `Perfil: ${payload.perfil_profissional || '-'}`,
  `Objetivo: ${payload.objetivo_do_lead || '-'}`,
  `Momento: ${payload.momento_de_compra || '-'}`,
  `Temperatura: ${payload.temperatura_lead}`,
  `Score: ${payload.score_inicial}`,
  payload.observacao ? `Obs: ${payload.observacao}` : '',
  payload.utm_campaign ? `Campanha: ${payload.utm_campaign}` : ''
].filter(Boolean).join('\n');

return [{ json: payload }];
